**What this code covers**

- Complete REST API with pagination, filtering, validation, HATEOAS
- GET /users — List with cursor pagination and filtering
- GET /users/:id — Get single resource
- POST /users — Create a new resource
- Query 1: Get only name and email (no over-fetching)
- Query 2: Get user with nested posts in ONE request
- {'user': {'name': 'Alice', 'posts': [
- {'title': 'GraphQL Intro', 'likes': 42},

**Defines:** `require_auth()`, `validate_json()`, `user_links()`, `list_users()`, `get_user()`, `create_user()`, `update_user()`, `delete_user()`, `not_found()`, `server_error()`

### Example 1: RESTful API with Flask

```python
"""
Complete REST API with pagination, filtering, validation, HATEOAS
"""
from flask import Flask, request, jsonify, url_for
from functools import wraps
from datetime import datetime
import uuid

app = Flask(__name__)

# In-memory database
users_db = {}
API_VERSION = "v1"

# --- Middleware ---
def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get("Authorization", "").replace("Bearer ", "")
        if not token or token != "valid-token":  # Simplified
            return jsonify({"error": "Unauthorized"}), 401
        return f(*args, **kwargs)
    return decorated

def validate_json(*required_fields):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            data = request.get_json()
            if not data:
                return jsonify({"error": "JSON body required"}), 400
            missing = [field for field in required_fields if field not in data]
            if missing:
                return jsonify({"error": f"Missing fields: {missing}"}), 400
            return f(*args, **kwargs)
        return decorated
    return decorator

# --- HATEOAS Links ---
def user_links(user_id):
    return {
        "self": f"/api/{API_VERSION}/users/{user_id}",
        "orders": f"/api/{API_VERSION}/users/{user_id}/orders",
        "collection": f"/api/{API_VERSION}/users"
    }

# --- Routes ---
@app.route(f"/api/{API_VERSION}/users", methods=["GET"])
@require_auth
def list_users():
    """GET /users — List with cursor pagination and filtering"""
    # Pagination
    cursor = request.args.get("cursor")
    limit = min(int(request.args.get("limit", 20)), 100)

    # Filtering
    role = request.args.get("role")

    all_users = sorted(users_db.values(), key=lambda u: u["created_at"])

    if role:
        all_users = [u for u in all_users if u.get("role") == role]

    # Cursor-based pagination
    start_idx = 0
    if cursor:
        for i, u in enumerate(all_users):
            if u["id"] == cursor:
                start_idx = i + 1
                break

    page = all_users[start_idx:start_idx + limit]
    next_cursor = page[-1]["id"] if len(page) == limit else None

    return jsonify({
        "data": page,
        "pagination": {
            "next_cursor": next_cursor,
            "limit": limit,
            "total": len(all_users)
        },
        "links": {
            "self": f"/api/{API_VERSION}/users?cursor={cursor}&limit={limit}",
            "next": f"/api/{API_VERSION}/users?cursor={next_cursor}&limit={limit}" if next_cursor else None
        }
    })

@app.route(f"/api/{API_VERSION}/users/<user_id>", methods=["GET"])
@require_auth
def get_user(user_id):
    """GET /users/:id — Get single resource"""
    user = users_db.get(user_id)
    if not user:
        return jsonify({"error": "User not found"}), 404

    return jsonify({
        "data": user,
        "_links": user_links(user_id)
    })

@app.route(f"/api/{API_VERSION}/users", methods=["POST"])
@require_auth
@validate_json("name", "email")
def create_user():
    """POST /users — Create a new resource"""
    data = request.get_json()
    user_id = str(uuid.uuid4())

    user = {
        "id": user_id,
        "name": data["name"],
        "email": data["email"],
        "role": data.get("role", "user"),
        "created_at": datetime.utcnow().isoformat()
    }
    users_db[user_id] = user

    return jsonify({
        "data": user,
        "_links": user_links(user_id)
    }), 201

@app.route(f"/api/{API_VERSION}/users/<user_id>`, methods=["PATCH"])
@require_auth
def update_user(user_id):
    """PATCH /users/:id — Partial update"""
    user = users_db.get(user_id)
    if not user:
        return jsonify({"error": "User not found"}), 404

    data = request.get_json()
    allowed = {"name", "email", "role"}
    updates = {k: v for k, v in data.items() if k in allowed}
    user.update(updates)

    return jsonify({"data": user, "_links": user_links(user_id)})

@app.route(f"/api/{API_VERSION}/users/<user_id>", methods=["DELETE"])
@require_auth
def delete_user(user_id):
    """DELETE /users/:id — Remove resource"""
    if user_id not in users_db:
        return jsonify({"error": "User not found"}), 404
    del users_db[user_id]
    return "", 204

# Error handlers
@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "Resource not found"}), 404

@app.errorhandler(500)
def server_error(e):
    return jsonify({"error": "Internal server error"}), 500
```

### Example 2: GraphQL API with Graphene

```python
"""
GraphQL API — client specifies exact fields needed
"""
import graphene
from graphene import ObjectType, String, Int, List, Field, Mutation
from datetime import datetime

# Simulated database
USERS = {
    "1": {"id": "1", "name": "Alice", "email": "alice@io.com", "age": 30},
    "2": {"id": "2", "name": "Bob", "email": "bob@io.com", "age": 25},
}
POSTS = [
    {"id": "p1", "title": "GraphQL Intro", "author_id": "1", "likes": 42},
    {"id": "p2", "title": "REST Best Practices", "author_id": "1", "likes": 38},
    {"id": "p3", "title": "gRPC Guide", "author_id": "2", "likes": 27},
]

# --- Schema Types ---
class PostType(ObjectType):
    id = String()
    title = String()
    author_id = String()
    likes = Int()

class UserType(ObjectType):
    id = String()
    name = String()
    email = String()
    age = Int()
    posts = List(PostType)

    def resolve_posts(parent, info):
        """Resolve nested posts — avoids N+1 problem with DataLoader"""
        return [p for p in POSTS if p["author_id"] == parent["id"]]

# --- Queries ---
class Query(ObjectType):
    user = Field(UserType, id=String(required=True))
    users = List(UserType, limit=Int(default_value=10))
    post = Field(PostType, id=String(required=True))

    def resolve_user(root, info, id):
        return USERS.get(id)

    def resolve_users(root, info, limit):
        return list(USERS.values())[:limit]

    def resolve_post(root, info, id):
        return next((p for p in POSTS if p["id"] == id), None)

# --- Mutations ---
class CreateUser(Mutation):
    class Arguments:
        name = String(required=True)
        email = String(required=True)
        age = Int()

    user = Field(UserType)

    def mutate(root, info, name, email, age=None):
        user_id = str(len(USERS) + 1)
        user = {"id": user_id, "name": name, "email": email, "age": age}
        USERS[user_id] = user
        return CreateUser(user=user)

class Mutations(ObjectType):
    create_user = CreateUser.Field()

schema = graphene.Schema(query=Query, mutation=Mutations)

# Example queries
# Query 1: Get only name and email (no over-fetching)
result = schema.execute('{ user(id: "1") { name email } }')
print(result.data)  # {'user': {'name': 'Alice', 'email': 'alice@io.com'}}

# Query 2: Get user with nested posts in ONE request
result = schema.execute('{ user(id: "1") { name posts { title likes } } }')
print(result.data)
# {'user': {'name': 'Alice', 'posts': [
#   {'title': 'GraphQL Intro', 'likes': 42},
#   {'title': 'REST Best Practices', 'likes': 38}]}}
```

### Example 3: gRPC Service Definition and Client

```python
"""
gRPC service — high-performance binary protocol
Proto file would define the service; below simulates the pattern
"""
from dataclasses import dataclass
from typing import Iterator, List
import struct
import json
import time

# Simulated Protocol Buffer message classes
@dataclass
class UserRequest:
    user_id: str

    def serialize(self) -> bytes:
        return json.dumps({"user_id": self.user_id}).encode()

    @classmethod
    def deserialize(cls, data: bytes) -> 'UserRequest':
        d = json.loads(data.decode())
        return cls(**d)

@dataclass
class UserResponse:
    user_id: str
    name: str
    email: str

    def serialize(self) -> bytes:
        return json.dumps({"user_id": self.user_id, "name": self.name, "email": self.email}).encode()

    @classmethod
    def deserialize(cls, data: bytes) -> 'UserResponse':
        d = json.loads(data.decode())
        return cls(**d)

# gRPC Service Implementation
class UserServiceServicer:
    """Server-side gRPC service"""

    def __init__(self):
        self.users = {
            "1": {"name": "Alice", "email": "alice@io.com"},
            "2": {"name": "Bob", "email": "bob@io.com"},
        }

    def GetUser(self, request: UserRequest) -> UserResponse:
        """Unary RPC: One request → One response"""
        user = self.users.get(request.user_id)
        if not user:
            raise Exception(f"User {request.user_id} not found")
        return UserResponse(
            user_id=request.user_id,
            name=user["name"],
            email=user["email"]
        )

    def ListUsers(self, request) -> Iterator[UserResponse]:
        """Server streaming: One request → Stream of responses"""
        for uid, user in self.users.items():
            yield UserResponse(user_id=uid, name=user["name"], email=user["email"])

    def UploadUsers(self, requests: Iterator[UserRequest]) -> dict:
        """Client streaming: Stream of requests → One response"""
        count = 0
        for req in requests:
            count += 1
        return {"processed": count}

    def Chat(self, requests: Iterator) -> Iterator:
        """Bidirectional streaming: Stream ↔ Stream"""
        for req in requests:
            yield UserResponse(user_id=req.user_id, name="Echo", email="echo@io.com")

# Client
service = UserServiceServicer()

# Unary call
response = service.GetUser(UserRequest(user_id="1"))
print(f"Got user: {response.name}")

# Server streaming
for user in service.ListUsers(None):
    print(f"Streaming: {user.name}")
```

### Example 4: API Rate Limiter

```python
"""
Token bucket rate limiter for API protection
"""
import time
import threading
from dataclasses import dataclass, field
from typing import Dict, Optional

@dataclass
class TokenBucket:
    capacity: int
    tokens: float
    refill_rate: float  # tokens per second
    last_refill: float = field(default_factory=time.time)

    def consume(self, tokens: int = 1) -> bool:
        now = time.time()
        # Refill tokens based on elapsed time
        elapsed = now - self.last_refill
        self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_rate)
        self.last_refill = now

        if self.tokens >= tokens:
            self.tokens -= tokens
            return True
        return False

class APIRateLimiter:
    """Per-client rate limiting with multiple tiers"""

    TIERS = {
        "free":       {"capacity": 10,  "rate": 1},    # 10 burst, 1/sec
        "basic":      {"capacity": 50,  "rate": 10},   # 50 burst, 10/sec
        "premium":    {"capacity": 200, "rate": 50},    # 200 burst, 50/sec
        "enterprise": {"capacity": 1000, "rate": 200},  # 1000 burst, 200/sec
    }

    def __init__(self):
        self.buckets: Dict[str, TokenBucket] = {}
        self.lock = threading.Lock()

    def get_bucket(self, client_id: str, tier: str = "free") -> TokenBucket:
        with self.lock:
            if client_id not in self.buckets:
                config = self.TIERS.get(tier, self.TIERS["free"])
                self.buckets[client_id] = TokenBucket(
                    capacity=config["capacity"],
                    tokens=config["capacity"],
                    refill_rate=config["rate"]
                )
            return self.buckets[client_id]

    def allow_request(self, client_id: str, tier: str = "free") -> dict:
        bucket = self.get_bucket(client_id, tier)
        allowed = bucket.consume()

        return {
            "allowed": allowed,
            "headers": {
                "X-RateLimit-Limit": bucket.capacity,
                "X-RateLimit-Remaining": max(0, int(bucket.tokens)),
                "X-RateLimit-Reset": int(time.time() + bucket.capacity / bucket.refill_rate),
                "Retry-After": 0 if allowed else int(1 / bucket.refill_rate)
            }
        }

# Usage
limiter = APIRateLimiter()

for i in range(15):
    result = limiter.allow_request("client-123", tier="free")
    status = "✓ Allowed" if result["allowed"] else "✗ Rate limited (429)"
    print(f"Request {i+1}: {status} | Remaining: {result['headers']['X-RateLimit-Remaining']}")
```

### Example 5: API Gateway Pattern

```python
"""
API Gateway: single entry point for multiple microservices
"""
from dataclasses import dataclass
from typing import Dict, Optional, Callable
import time
import hashlib

@dataclass
class Route:
    path_prefix: str
    service_url: str
    methods: list
    auth_required: bool = True
    rate_limit: int = 100  # requests/minute
    cache_ttl: int = 0     # seconds, 0 = no cache
    transform: Optional[Callable] = None  # Response transformer

class APIGateway:
    """Centralized API Gateway"""

    def __init__(self):
        self.routes: Dict[str, Route] = {}
        self.cache: Dict[str, dict] = {}
        self.request_counts: Dict[str, list] = {}

    def register_route(self, route: Route):
        self.routes[route.path_prefix] = route

    def handle_request(self, method: str, path: str, headers: dict, body: dict = None):
        """Process incoming request through gateway pipeline"""
        start = time.time()

        # 1. Route matching
        route = self._match_route(path)
        if not route:
            return self._response(404, {"error": "Route not found"})

        # 2. Method check
        if method not in route.methods:
            return self._response(405, {"error": f"Method {method} not allowed"})

        # 3. Authentication
        if route.auth_required:
            auth_result = self._authenticate(headers)
            if not auth_result["valid"]:
                return self._response(401, {"error": "Unauthorized"})

        # 4. Rate limiting
        client_id = headers.get("X-Client-ID", "anonymous")
        if not self._check_rate_limit(client_id, route.rate_limit):
            return self._response(429, {"error": "Rate limit exceeded"})

        # 5. Cache check (GET only)
        if method == "GET" and route.cache_ttl > 0:
            cached = self._check_cache(path)
            if cached:
                return self._response(200, cached, headers={"X-Cache": "HIT"})

        # 6. Forward to service
        response = self._forward_request(route, method, path, body)

        # 7. Cache response
        if method == "GET" and route.cache_ttl > 0:
            self._set_cache(path, response, route.cache_ttl)

        # 8. Transform response
        if route.transform:
            response = route.transform(response)

        latency = (time.time() - start) * 1000
        return self._response(200, response, headers={
            "X-Gateway-Latency": f"{latency:.2f}ms",
            "X-Cache": "MISS"
        })

    def _match_route(self, path: str) -> Optional[Route]:
        for prefix, route in self.routes.items():
            if path.startswith(prefix):
                return route
        return None

    def _authenticate(self, headers: dict) -> dict:
        token = headers.get("Authorization", "")
        return {"valid": token.startswith("Bearer ")}

    def _check_rate_limit(self, client_id: str, limit: int) -> bool:
        now = time.time()
        if client_id not in self.request_counts:
            self.request_counts[client_id] = []

        # Remove requests older than 1 minute
        self.request_counts[client_id] = [
            t for t in self.request_counts[client_id] if now - t < 60
        ]

        if len(self.request_counts[client_id]) >= limit:
            return False

        self.request_counts[client_id].append(now)
        return True

    def _check_cache(self, key: str) -> Optional[dict]:
        entry = self.cache.get(key)
        if entry and time.time() < entry["expires"]:
            return entry["data"]
        return None

    def _set_cache(self, key: str, data: dict, ttl: int):
        self.cache[key] = {"data": data, "expires": time.time() + ttl}

    def _forward_request(self, route: Route, method: str, path: str, body: dict):
        # Simulated service call
        return {"service": route.service_url, "path": path, "status": "ok"}

    def _response(self, status: int, body: dict, headers: dict = None):
        return {"status": status, "body": body, "headers": headers or {}}

# Setup
gateway = APIGateway()

gateway.register_route(Route(
    path_prefix="/api/users",
    service_url="http://user-service:8080",
    methods=["GET", "POST", "PATCH", "DELETE"],
    cache_ttl=60  # Cache GET for 60s
))

gateway.register_route(Route(
    path_prefix="/api/orders",
    service_url="http://order-service:8080",
    methods=["GET", "POST"],
    rate_limit=50
))

# Process requests
result = gateway.handle_request(
    "GET", "/api/users/123",
    headers={"Authorization": "Bearer token123", "X-Client-ID": "client-1"}
)
print(result)
```
